paired_loop.patch:
diff --git a/src/regexec.rs b/src/regexec.rs
index 222dee6..d326d51 100644
--- a/src/regexec.rs
+++ b/src/regexec.rs
@@ -2790,10 +2790,18 @@ pub(crate) fn is_in_code_range(data: &[u32], code: OnigCodePoint) -> bool {
         return false;
     }

-    // Search whole pairs so the library's binary search can select the next
-    // interval without a data-dependent branch or repeated pair indexing.
+    // Keep paired indexing without forcing the branchless partition search.
     let (pairs, _) = ranges.as_chunks::<2>();
-    let low = pairs.partition_point(|range| range[1] < code);
+    let mut low = 0;
+    let mut high = pairs.len();
+    while low < high {
+        let x = (low + high) >> 1;
+        if code > pairs[x][1] {
+            low = x + 1;
+        } else {
+            high = x;
+        }
+    }
     low < n && code >= pairs[low][0]
 }

interval_search.patch:
diff --git a/src/regexec.rs b/src/regexec.rs
index 222dee6..35649c0 100644
--- a/src/regexec.rs
+++ b/src/regexec.rs
@@ -2790,11 +2790,21 @@ pub(crate) fn is_in_code_range(data: &[u32], code: OnigCodePoint) -> bool {
         return false;
     }

-    // Search whole pairs so the library's binary search can select the next
-    // interval without a data-dependent branch or repeated pair indexing.
-    let (pairs, _) = ranges.as_chunks::<2>();
-    let low = pairs.partition_point(|range| range[1] < code);
-    low < n && code >= pairs[low][0]
+    // Slice by complete intervals so midpoint and tail accesses stay bounded.
+    let (mut pairs, _) = ranges.as_chunks::<2>();
+    while !pairs.is_empty() {
+        let (left, right) = pairs.split_at(pairs.len() / 2);
+        // The midpoint of a nonempty slice is strictly below its length.
+        let (range, tail) = right.split_first().unwrap();
+        if code > range[1] {
+            pairs = tail;
+        } else if code < range[0] {
+            pairs = left;
+        } else {
+            return true;
+        }
+    }
+    false
 }

